from datetime import datetime

class Chat:
    def __init__(self):
        self._users = {}

    def _create_message_info(self, sender, receiver, message, timestamp):
        return {
            'sender': sender,
            'receiver': receiver,
            'message': message,
            'timestamp': timestamp
        }

    def add_user(self, username):
        if username in self._users:
            return False
        self._users[username] = []
        return True

    def remove_user(self, username):
        if username in self._users:
            del self._users[username]
            return True
        return False

    def send_message(self, sender, receiver, message):
        if not self._is_valid_user(sender) or not self._is_valid_user(receiver):
            return False

        timestamp = self._get_current_timestamp()
        message_info = self._create_message_info(sender, receiver, message, timestamp)
        self._users[sender].append(message_info)
        self._users[receiver].append(message_info)
        return True

    def get_messages(self, username):
        if not self._is_valid_user(username):
            return []
        return self._get_user_messages(username)

    def _is_valid_user(self, username):
        return username in self._users

    def _get_current_timestamp(self):
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def _get_user_messages(self, username):
        return self._users[username]

    @property
    def users(self):
        return dict(self._users)

    @property
    def size(self):
        return len(self._users)
